x_938076_backup_0_backup_scripts.script:
function setHintsAndMakeFieldMandatory() {
	// Make rank field mandatory on samp_named_user_type table
	new global.GlideQuery('sys_dictionary')
		.where('name', 'samp_named_user_type')
		.where('element', 'rank')
		.updateMultiple({
			mandatory: true,
		});

	// Set hint for rank field on samp_named_user_type table
	new global.GlideQuery('sys_documentation')
		.where('name', 'samp_named_user_type')
		.where('element', 'rank')
		.updateMultiple({
			hint: 'Named user type sort/ranking value in SAP',
		});

	// Set hint for value field on samp_named_user_type table
	new global.GlideQuery('sys_documentation')
		.where('name', 'samp_named_user_type')
		.where('element', 'value')
		.updateMultiple({
			hint: 'Named user type value in SAP',
		});
}
setHintsAndMakeFieldMandatory();
